function knifeDrop(p){return p.x>.85&&p.x<1.5&&p.z>1.22&&p.z<1.85}
function inSink(p){return p.x> -5.45&&p.x< -3.05&&p.z> -1.8&&p.z<.8}
function near(p,q,d=1){return Math.hypot(p.x-q.x,p.z-q.z)<d}
function rayHits(o){return o&&o.visible!==false&&ray.intersectObjects(o.children.length?o.children:[o],true).length>0}
